-- ============================================================================
-- 黔能碳溯（QNCT）· MySQL 8.0 核心表结构设计（DDL）
-- 贵州省重点产业碳足迹双轨合规与多级溯源智能系统
-- ----------------------------------------------------------------------------
-- 规范说明：
--   1) 字符集 utf8mb4 / 排序规则 utf8mb4_unicode_ci，兼容中文与 emoji。
--   2) 通用字段：id 主键、create_time、update_time、create_by(操作人id)、
--      update_by、deleted(逻辑删除 0/1)。
--   3) 金额/排放量统一 DECIMAL，避免浮点误差；状态用 VARCHAR 便于可读与扩展。
--   4) 为“两周极速交付”，表间采用逻辑外键 + 索引（不建硬外键约束），
--      由应用层维护一致性；业务编号统一冗余 biz_no 以便检索。
--   5) 所有平台字典值在 sys_dict_item 维护，避免散落的常量。
-- ============================================================================

CREATE DATABASE IF NOT EXISTS `qnct`
  DEFAULT CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE `qnct`;

-- ============================================================================
-- 一、平台域：组织 / 用户 / RBAC / 字典 / 配置 / 通知
-- ============================================================================

-- 1. 组织/机构表（企业、省厅及下辖部门、核查机构、平台自身）
DROP TABLE IF EXISTS `sys_org`;
CREATE TABLE `sys_org` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_type`       VARCHAR(20)  NOT NULL COMMENT '机构类型: PLATFORM平台/GOV省厅/AGENCY核查机构/ENTERPRISE企业',
  `name`           VARCHAR(128) NOT NULL COMMENT '机构全称',
  `short_name`     VARCHAR(64)  DEFAULT NULL COMMENT '简称',
  `org_code`       VARCHAR(64)  DEFAULT NULL COMMENT '统一社会信用代码',
  `parent_id`      BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '上级机构id(省厅下设市/州子节点)',
  `province`       VARCHAR(32)  DEFAULT NULL COMMENT '省',
  `city`           VARCHAR(32)  DEFAULT NULL COMMENT '市/州',
  `district`       VARCHAR(32)  DEFAULT NULL COMMENT '区/县',
  `address`        VARCHAR(255) DEFAULT NULL COMMENT '详细地址',
  `industry_code`  VARCHAR(32)  DEFAULT NULL COMMENT '国民经济行业代码',
  `industry_type`  VARCHAR(64)  DEFAULT NULL COMMENT '行业分类: 煤炭开采/新能源材料/其他',
  `legal_person`   VARCHAR(64)  DEFAULT NULL COMMENT '法定代表人',
  `contact_name`   VARCHAR(64)  DEFAULT NULL COMMENT '联系人',
  `contact_phone`  VARCHAR(32)  DEFAULT NULL COMMENT '联系电话',
  `credit_rating`  VARCHAR(8)   DEFAULT NULL COMMENT '信用等级',
  `logo_url`       VARCHAR(255) DEFAULT NULL COMMENT 'Logo地址',
  `license_url`    VARCHAR(255) DEFAULT NULL COMMENT '营业执照/资质文件地址',
  `status`         VARCHAR(16)  NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED启用/DISABLED停用/PENDING待审核',
  `create_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by`      BIGINT UNSIGNED DEFAULT NULL COMMENT '创建人id',
  `update_by`      BIGINT UNSIGNED DEFAULT NULL COMMENT '更新人id',
  `deleted`        TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0否/1是',
  PRIMARY KEY (`id`),
  KEY `idx_org_type` (`org_type`),
  KEY `idx_org_code` (`org_code`),
  KEY `idx_org_parent` (`parent_id`),
  KEY `idx_org_region` (`province`,`city`,`district`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='组织/机构表';

-- 2. 用户表
DROP TABLE IF EXISTS `sys_user`;
CREATE TABLE `sys_user` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_id`          BIGINT UNSIGNED NOT NULL COMMENT '所属机构id',
  `username`        VARCHAR(64)  NOT NULL COMMENT '登录账号',
  `password`        VARCHAR(255) NOT NULL COMMENT '密码哈希(BCrypt)',
  `real_name`       VARCHAR(64)  DEFAULT NULL COMMENT '真实姓名',
  `phone`           VARCHAR(32)  DEFAULT NULL COMMENT '手机号',
  `email`           VARCHAR(128) DEFAULT NULL COMMENT '邮箱',
  `avatar`          VARCHAR(255) DEFAULT NULL COMMENT '头像地址',
  `user_type`       VARCHAR(20)  NOT NULL COMMENT '用户类型: ADMIN超管/GOV监管/AGENCY核查/ENTERPRISE企业',
  `position`        VARCHAR(64)  DEFAULT NULL COMMENT '岗位/职务',
  `status`          VARCHAR(16)  NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED/DISABLED/LOCKED',
  `last_login_time` DATETIME DEFAULT NULL COMMENT '最后登录时间',
  `last_login_ip`   VARCHAR(64)  DEFAULT NULL COMMENT '最后登录IP',
  `create_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by`       BIGINT UNSIGNED DEFAULT NULL COMMENT '创建人id',
  `update_by`       BIGINT UNSIGNED DEFAULT NULL COMMENT '更新人id',
  `deleted`         TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_username` (`username`),
  KEY `idx_user_org` (`org_id`),
  KEY `idx_user_phone` (`phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户表';

-- 3. 角色表
DROP TABLE IF EXISTS `sys_role`;
CREATE TABLE `sys_role` (
  `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_code`   VARCHAR(64)  NOT NULL COMMENT '角色编码: SUPER_ADMIN/GOV_ADMIN/GOV_REVIEWER/GOV_INSPECTOR/AGENCY_REVIEWER/ENT_ADMIN/ENT_USER...',
  `role_name`   VARCHAR(64)  NOT NULL COMMENT '角色名称',
  `role_type`   VARCHAR(20)  NOT NULL COMMENT '角色归属: ADMIN/GOV/AGENCY/ENTERPRISE',
  `data_scope`  VARCHAR(20)  NOT NULL DEFAULT 'SELF_ORG' COMMENT '数据范围: ALL全部/REGION辖区/ORG本机构/SELF本人',
  `remark`      VARCHAR(255) DEFAULT NULL COMMENT '备注',
  `status`      VARCHAR(16)  NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED/DISABLED',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`     TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_code` (`role_code`),
  KEY `idx_role_type` (`role_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='角色表';

-- 4. 权限/菜单表
DROP TABLE IF EXISTS `sys_permission`;
CREATE TABLE `sys_permission` (
  `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parent_id`   BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '父级id(树形菜单)',
  `perm_type`   VARCHAR(16)  NOT NULL DEFAULT 'MENU' COMMENT '类型: MENU菜单/BUTTON按钮/API接口',
  `perm_code`   VARCHAR(128) NOT NULL COMMENT '权限标识, 如 ent:report:export',
  `perm_name`   VARCHAR(64)  NOT NULL COMMENT '权限名称',
  `route_path`  VARCHAR(255) DEFAULT NULL COMMENT '前端路由路径',
  `component`   VARCHAR(255) DEFAULT NULL COMMENT '前端组件路径',
  `icon`        VARCHAR(64)  DEFAULT NULL COMMENT '图标',
  `sort`        INT NOT NULL DEFAULT 0 COMMENT '排序',
  `visible`     TINYINT NOT NULL DEFAULT 1 COMMENT '是否可见: 0否/1是',
  `status`      VARCHAR(16)  NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED/DISABLED',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`     TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_perm_code` (`perm_code`),
  KEY `idx_perm_parent` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='权限/菜单表';

-- 5. 用户-角色关联表
DROP TABLE IF EXISTS `sys_user_role`;
CREATE TABLE `sys_user_role` (
  `id`      BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` BIGINT UNSIGNED NOT NULL COMMENT '用户id',
  `role_id` BIGINT UNSIGNED NOT NULL COMMENT '角色id',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_role` (`user_id`,`role_id`),
  KEY `idx_ur_role` (`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户-角色关联表';

-- 6. 角色-权限关联表
DROP TABLE IF EXISTS `sys_role_permission`;
CREATE TABLE `sys_role_permission` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_id`       BIGINT UNSIGNED NOT NULL COMMENT '角色id',
  `permission_id` BIGINT UNSIGNED NOT NULL COMMENT '权限id',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_perm` (`role_id`,`permission_id`),
  KEY `idx_rp_perm` (`permission_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='角色-权限关联表';

-- 7. 数据字典类型
DROP TABLE IF EXISTS `sys_dict_type`;
CREATE TABLE `sys_dict_type` (
  `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dict_code`   VARCHAR(64) NOT NULL COMMENT '字典编码, 如 INDUSTRY_TYPE',
  `dict_name`   VARCHAR(64) NOT NULL COMMENT '字典名称',
  `remark`      VARCHAR(255) DEFAULT NULL COMMENT '备注',
  `status`      VARCHAR(16) NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED/DISABLED',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dict_code` (`dict_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='数据字典类型表';

-- 8. 数据字典项
DROP TABLE IF EXISTS `sys_dict_item`;
CREATE TABLE `sys_dict_item` (
  `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dict_code`   VARCHAR(64) NOT NULL COMMENT '所属字典编码',
  `item_label`  VARCHAR(64) NOT NULL COMMENT '显示名称',
  `item_value`  VARCHAR(64) NOT NULL COMMENT '存储值',
  `sort`        INT NOT NULL DEFAULT 0 COMMENT '排序',
  `enabled`     TINYINT NOT NULL DEFAULT 1 COMMENT '是否启用: 0否/1是',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_dict_item_code` (`dict_code`),
  KEY `idx_dict_item_enabled` (`dict_code`,`enabled`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='数据字典项表';

-- 9. 系统配置表
DROP TABLE IF EXISTS `sys_config`;
CREATE TABLE `sys_config` (
  `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `config_key`  VARCHAR(128) NOT NULL COMMENT '配置键',
  `config_value` TEXT DEFAULT NULL COMMENT '配置值',
  `config_desc` VARCHAR(255) DEFAULT NULL COMMENT '配置说明',
  `is_secret`   TINYINT NOT NULL DEFAULT 0 COMMENT '是否敏感: 0否/1是(加密存储)',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_config_key` (`config_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统配置表';

-- 10. 站内通知表
DROP TABLE IF EXISTS `sys_notification`;
CREATE TABLE `sys_notification` (
  `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id`     BIGINT UNSIGNED NOT NULL COMMENT '接收用户id',
  `biz_type`    VARCHAR(64) DEFAULT NULL COMMENT '业务类型: REVIEW/INSPECTION/PASSPORT/PACKAGE...',
  `title`       VARCHAR(128) NOT NULL COMMENT '标题',
  `content`     TEXT DEFAULT NULL COMMENT '内容',
  `read_flag`   TINYINT NOT NULL DEFAULT 0 COMMENT '是否已读: 0否/1是',
  `read_time`   DATETIME DEFAULT NULL COMMENT '阅读时间',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_notify_user` (`user_id`,`read_flag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='站内通知表';

-- ============================================================================
-- 二、平台域：文件 / 审计 / 哈希链存证 / 监控指标
-- ============================================================================

-- 11. 文件表（统一管理 OSS/本地文件）
DROP TABLE IF EXISTS `sys_file`;
CREATE TABLE `sys_file` (
  `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_id`       BIGINT UNSIGNED DEFAULT NULL COMMENT '所属机构id',
  `user_id`      BIGINT UNSIGNED DEFAULT NULL COMMENT '上传人id',
  `file_name`    VARCHAR(255) NOT NULL COMMENT '原始文件名',
  `file_path`    VARCHAR(500) NOT NULL COMMENT '存储路径/OSS Key',
  `file_type`    VARCHAR(64)  DEFAULT NULL COMMENT '文件类型: IMAGE/PDF/DOCX/ZIP/XLSX',
  `file_size`    BIGINT UNSIGNED DEFAULT 0 COMMENT '文件大小(字节)',
  `md5`          CHAR(32)     DEFAULT NULL COMMENT 'MD5摘要',
  `storage_type` VARCHAR(16)  NOT NULL DEFAULT 'LOCAL' COMMENT 'LOCAL本地/OSS',
  `bucket`       VARCHAR(128) DEFAULT NULL COMMENT 'OSS Bucket',
  `biz_type`     VARCHAR(32)  DEFAULT NULL COMMENT '业务来源: LAB_REPORT/CHECKIN_PHOTO/REPORT_FILE/PACKAGE...',
  `biz_id`       BIGINT UNSIGNED DEFAULT NULL COMMENT '关联业务id',
  `create_time`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted`      TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_file_biz` (`biz_type`,`biz_id`),
  KEY `idx_file_md5` (`md5`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文件表';

-- 12. 全量审计日志表
DROP TABLE IF EXISTS `sys_audit_log`;
CREATE TABLE `sys_audit_log` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id`         BIGINT UNSIGNED DEFAULT NULL COMMENT '操作人id',
  `username`        VARCHAR(64) DEFAULT NULL COMMENT '操作人账号(冗余)',
  `real_name`       VARCHAR(64) DEFAULT NULL COMMENT '操作人姓名(冗余)',
  `org_id`          BIGINT UNSIGNED DEFAULT NULL COMMENT '机构id',
  `module`          VARCHAR(64) DEFAULT NULL COMMENT '模块: AUTH/CARBON/PACKAGE/PASSPORT/RBAC...',
  `action`          VARCHAR(64) DEFAULT NULL COMMENT '操作: LOGIN/EXPORT/REVIEW/ISSUE/DELETE...',
  `resource_type`   VARCHAR(64) DEFAULT NULL COMMENT '资源类型',
  `resource_id`     BIGINT UNSIGNED DEFAULT NULL COMMENT '资源id',
  `method`          VARCHAR(16) DEFAULT NULL COMMENT 'HTTP方法',
  `url`             VARCHAR(255) DEFAULT NULL COMMENT '请求URL',
  `ip`              VARCHAR(64) DEFAULT NULL COMMENT '来源IP',
  `user_agent`      VARCHAR(255) DEFAULT NULL COMMENT 'User-Agent',
  `request_params`  TEXT DEFAULT NULL COMMENT '请求参数(脱敏)',
  `response_status` INT DEFAULT NULL COMMENT '响应状态码',
  `result`          VARCHAR(16) DEFAULT NULL COMMENT 'SUCCESS/FAIL',
  `duration_ms`     INT DEFAULT NULL COMMENT '耗时(毫秒)',
  `operate_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`),
  KEY `idx_audit_user` (`user_id`,`operate_time`),
  KEY `idx_audit_module` (`module`,`operate_time`),
  KEY `idx_audit_ip` (`ip`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='全量审计日志表';

-- 13. 哈希链防篡改存证表（轻量级 Hash Chain）
DROP TABLE IF EXISTS `sys_hash_chain`;
CREATE TABLE `sys_hash_chain` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `block_seq`     BIGINT UNSIGNED NOT NULL COMMENT '链上序号(全局递增)',
  `prev_hash`     CHAR(64) NOT NULL COMMENT '前一区块哈希(SHA256), 创世块为全0',
  `data_hash`     CHAR(64) NOT NULL COMMENT '本区块数据哈希',
  `biz_type`      VARCHAR(32) NOT NULL COMMENT '业务类型: CARBON_RESULT/CARBON_REPORT/PASSPORT/PACKAGE',
  `biz_id`        BIGINT UNSIGNED NOT NULL COMMENT '业务id',
  `biz_no`        VARCHAR(64) DEFAULT NULL COMMENT '业务编号(冗余便于检索)',
  `payload_json`  JSON DEFAULT NULL COMMENT '存证摘要载荷(关键字段快照)',
  `operator_id`   BIGINT UNSIGNED DEFAULT NULL COMMENT '触发操作人id',
  `create_time`   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上链时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_chain_seq` (`block_seq`),
  UNIQUE KEY `uk_chain_biz` (`biz_type`,`biz_id`,`block_seq`),
  KEY `idx_chain_biz` (`biz_type`,`biz_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='哈希链防篡改存证表';

-- 14. 系统监控指标表（监控看板数据源）
DROP TABLE IF EXISTS `sys_server_metric`;
CREATE TABLE `sys_server_metric` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `metric_type`    VARCHAR(32) NOT NULL COMMENT '指标类型: CPU/MEM/DISK/ONLINE_USER/API_QPS',
  `metric_value`   DECIMAL(16,4) DEFAULT NULL COMMENT '指标值',
  `metric_detail`  JSON DEFAULT NULL COMMENT '明细(JSON)',
  `collect_time`   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '采集时间',
  PRIMARY KEY (`id`),
  KEY `idx_metric_type_time` (`metric_type`,`collect_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统监控指标表';

-- ============================================================================
-- 三、企业域：产品 / 工序设施 / 活动数据 / 化验单(OCR)
-- ============================================================================

-- 15. 企业产品表（碳足迹核算对象）
DROP TABLE IF EXISTS `ent_product`;
CREATE TABLE `ent_product` (
  `id`               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_id`           BIGINT UNSIGNED NOT NULL COMMENT '企业机构id',
  `product_code`     VARCHAR(64) DEFAULT NULL COMMENT '产品编码',
  `product_name`     VARCHAR(128) NOT NULL COMMENT '产品名称',
  `product_category` VARCHAR(64) DEFAULT NULL COMMENT '产品大类: 原煤/精煤/三元前驱体/磷酸铁锂...',
  `function_unit`    VARCHAR(64) DEFAULT NULL COMMENT '功能单位: 1t/1kWh/1kg',
  `annual_output`    DECIMAL(18,4) DEFAULT NULL COMMENT '年产量(功能单位)',
  `production_line`  VARCHAR(128) DEFAULT NULL COMMENT '产线/矿井',
  `status`           VARCHAR(16) NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED/DISABLED',
  `create_time`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`          TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_product_org` (`org_id`),
  KEY `idx_product_code` (`org_id`,`product_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='企业产品表';

-- 16. 工序/设施表（核算边界内的工序或设备）
DROP TABLE IF EXISTS `ent_facility`;
CREATE TABLE `ent_facility` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_id`        BIGINT UNSIGNED NOT NULL COMMENT '企业机构id',
  `product_id`    BIGINT UNSIGNED DEFAULT NULL COMMENT '所属产品id',
  `facility_code` VARCHAR(64) DEFAULT NULL COMMENT '工序/设施编码',
  `facility_name` VARCHAR(128) NOT NULL COMMENT '工序/设施名称: 采掘/洗选/干燥/焙烧/烧结...',
  `facility_type` VARCHAR(32) DEFAULT NULL COMMENT '类型: 能源使用/工艺排放/运输',
  `energy_type`   VARCHAR(32) DEFAULT NULL COMMENT '主要能源类型',
  `capacity`      DECIMAL(18,4) DEFAULT NULL COMMENT '产能/功率',
  `location`      VARCHAR(255) DEFAULT NULL COMMENT '位置',
  `status`        VARCHAR(16) NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED/DISABLED',
  `create_time`   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`       TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_facility_org` (`org_id`),
  KEY `idx_facility_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工序/设施表';

-- 17. 碳活动数据表（能源/物料/运输/工艺/废弃物统一采集）
DROP TABLE IF EXISTS `ent_activity_data`;
CREATE TABLE `ent_activity_data` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_id`         BIGINT UNSIGNED NOT NULL COMMENT '企业机构id',
  `product_id`     BIGINT UNSIGNED DEFAULT NULL COMMENT '产品id',
  `facility_id`    BIGINT UNSIGNED DEFAULT NULL COMMENT '工序/设施id',
  `period_type`    VARCHAR(16) NOT NULL COMMENT '周期类型: MONTH月/YEAR年',
  `period`         VARCHAR(16) NOT NULL COMMENT '周期值: 2026-11 或 2026',
  `activity_type`  VARCHAR(32) NOT NULL COMMENT '活动类型: ENERGY能源/MATERIAL原辅料/TRANSPORT运输/PROCESS工艺/WASTE废弃物',
  `activity_name`  VARCHAR(128) NOT NULL COMMENT '活动名称: 电力/柴油/天然气/原煤/石灰石...',
  `quantity`       DECIMAL(18,6) NOT NULL COMMENT '消耗量/用量',
  `unit`           VARCHAR(16) NOT NULL COMMENT '计量单位: t/万kWh/m3/km',
  `data_source`    VARCHAR(16) NOT NULL DEFAULT 'MANUAL' COMMENT '来源: MANUAL手工/METER抄表/OCR化验单/SUPPLY供应链',
  `source_ref`     VARCHAR(64) DEFAULT NULL COMMENT '来源单据号',
  `factor_id`      BIGINT UNSIGNED DEFAULT NULL COMMENT '采用的排放因子id(emission_factor)',
  `factor_value`   DECIMAL(18,6) DEFAULT NULL COMMENT '因子值快照(kgCO2e/unit)',
  `gwp`            DECIMAL(18,6) DEFAULT NULL COMMENT 'GWP折算系数',
  `emission_co2e`  DECIMAL(18,6) DEFAULT NULL COMMENT '该条活动数据碳排放(kgCO2e)',
  `scope`          VARCHAR(8) DEFAULT NULL COMMENT '排放范围: 1/2/3',
  `data_status`    VARCHAR(16) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT草稿/SUBMITTED已提交/CONFIRMED已确认',
  `submit_time`    DATETIME DEFAULT NULL COMMENT '提交时间',
  `create_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by`      BIGINT UNSIGNED DEFAULT NULL COMMENT '创建人id',
  `deleted`        TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_act_org_period` (`org_id`,`period`),
  KEY `idx_act_type` (`activity_type`),
  KEY `idx_act_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='碳活动数据表';

-- 18. 化验单主表（OCR 识别对象）
DROP TABLE IF EXISTS `lab_report`;
CREATE TABLE `lab_report` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_id`          BIGINT UNSIGNED NOT NULL COMMENT '企业机构id',
  `report_no`       VARCHAR(64) DEFAULT NULL COMMENT '化验单编号',
  `report_name`     VARCHAR(128) NOT NULL COMMENT '化验单名称',
  `sample_type`     VARCHAR(64) DEFAULT NULL COMMENT '样品类型: 原煤/煤矸石/碳酸锂/前驱体',
  `sample_date`     DATE DEFAULT NULL COMMENT '取样日期',
  `test_date`       DATE DEFAULT NULL COMMENT '化验日期',
  `lab_name`        VARCHAR(128) DEFAULT NULL COMMENT '化验机构',
  `file_id`         BIGINT UNSIGNED DEFAULT NULL COMMENT '原始图片文件id(sys_file)',
  `ocr_engine`      VARCHAR(16) DEFAULT NULL COMMENT '识别引擎: ALIYUN/PADDLE',
  `ocr_result_json` JSON DEFAULT NULL COMMENT 'OCR原始结构化结果',
  `ocr_confidence`  DECIMAL(6,4) DEFAULT NULL COMMENT '识别置信度',
  `parse_status`    VARCHAR(16) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING待识别/PARSING识别中/PARSED待复核/CONFIRMED已入库/FAILED失败',
  `confirm_by`      BIGINT UNSIGNED DEFAULT NULL COMMENT '复核人id',
  `confirm_time`    DATETIME DEFAULT NULL COMMENT '复核时间',
  `create_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`         TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_lab_org` (`org_id`,`create_time`),
  KEY `idx_lab_status` (`parse_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='化验单主表';

-- 19. 化验单明细表（OCR 抽取的结构化字段）
DROP TABLE IF EXISTS `lab_report_item`;
CREATE TABLE `lab_report_item` (
  `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `report_id`    BIGINT UNSIGNED NOT NULL COMMENT '化验单id',
  `item_name`    VARCHAR(64) NOT NULL COMMENT '指标名称: 低位发热量/含碳量/水分/灰分/挥发分/硫分/氧化锂含量...',
  `item_value`   DECIMAL(18,6) DEFAULT NULL COMMENT '指标值',
  `unit`         VARCHAR(32) DEFAULT NULL COMMENT '单位: MJ/kg/%， %等',
  `test_method`  VARCHAR(128) DEFAULT NULL COMMENT '检测标准/方法',
  `confidence`   DECIMAL(6,4) DEFAULT NULL COMMENT '该字段识别置信度',
  `manual_fixed` TINYINT NOT NULL DEFAULT 0 COMMENT '是否人工修正: 0否/1是',
  `create_time`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_lab_item_report` (`report_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='化验单明细表';

-- ============================================================================
-- 四、企业域：供应链协同 / 因子库 / 核算 / 报告 / 数据包 / 护照申请
-- ============================================================================

-- 20. 供应链伙伴表（供应商/客户）
DROP TABLE IF EXISTS `sc_supplier`;
CREATE TABLE `sc_supplier` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_id`        BIGINT UNSIGNED NOT NULL COMMENT '本企业机构id',
  `partner_type`  VARCHAR(16) NOT NULL COMMENT '伙伴类型: SUPPLIER供应商/CUSTOMER客户',
  `name`          VARCHAR(128) NOT NULL COMMENT '伙伴名称',
  `credit_code`   VARCHAR(64) DEFAULT NULL COMMENT '统一社会信用代码',
  `contact_name`  VARCHAR(64) DEFAULT NULL COMMENT '联系人',
  `contact_phone` VARCHAR(32) DEFAULT NULL COMMENT '联系电话',
  `material_scope` VARCHAR(255) DEFAULT NULL COMMENT '供应/采购物料范围',
  `region`        VARCHAR(64) DEFAULT NULL COMMENT '所在地',
  `status`        VARCHAR(16) NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED/DISABLED',
  `create_time`   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`       TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_sc_partner_org` (`org_id`,`partner_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='供应链伙伴表';

-- 21. 物料流转表（供应链协同数据）
DROP TABLE IF EXISTS `sc_material_flow`;
CREATE TABLE `sc_material_flow` (
  `id`                BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_id`            BIGINT UNSIGNED NOT NULL COMMENT '本企业机构id',
  `partner_id`        BIGINT UNSIGNED NOT NULL COMMENT '伙伴id',
  `flow_type`         VARCHAR(8) NOT NULL COMMENT '流向: IN采购/OUT销售',
  `material_name`     VARCHAR(128) NOT NULL COMMENT '物料名称',
  `quantity`          DECIMAL(18,6) NOT NULL COMMENT '数量',
  `unit`              VARCHAR(16) NOT NULL COMMENT '单位',
  `period`            VARCHAR(16) NOT NULL COMMENT '周期: 2026-11/2026',
  `transport_mode`    VARCHAR(32) DEFAULT NULL COMMENT '运输方式: 公路/铁路/水运',
  `transport_distance` DECIMAL(18,4) DEFAULT NULL COMMENT '运输距离(km)',
  `allocated_emission` DECIMAL(18,6) DEFAULT NULL COMMENT '分摊/关联碳排放(kgCO2e)',
  `status`            VARCHAR(16) NOT NULL DEFAULT 'CONFIRMED' COMMENT 'DRAFT/CONFIRMED',
  `create_time`       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`           TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_flow_org_period` (`org_id`,`period`),
  KEY `idx_flow_partner` (`partner_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='供应链物料流转表';

-- 22. 供应链协同任务表
DROP TABLE IF EXISTS `sc_collab_task`;
CREATE TABLE `sc_collab_task` (
  `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_id`      BIGINT UNSIGNED NOT NULL COMMENT '发起企业id',
  `partner_id`  BIGINT UNSIGNED DEFAULT NULL COMMENT '协同伙伴id',
  `task_type`   VARCHAR(32) NOT NULL COMMENT '任务类型: DATA_COLLECT数据收集/CONFIRM确认/FEEDBACK反馈',
  `title`       VARCHAR(128) NOT NULL COMMENT '标题',
  `content`     TEXT DEFAULT NULL COMMENT '内容',
  `deadline`    DATETIME DEFAULT NULL COMMENT '截止时间',
  `status`      VARCHAR(16) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING待处理/DOING处理中/DONE已完成/OVERDUE已逾期',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`     TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_collab_org` (`org_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='供应链协同任务表';

-- 23. 排放因子库表（省级因子库，含企业自定义）
DROP TABLE IF EXISTS `emission_factor`;
CREATE TABLE `emission_factor` (
  `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `factor_code`  VARCHAR(64) NOT NULL COMMENT '因子编码',
  `factor_name`  VARCHAR(128) NOT NULL COMMENT '因子名称: 电力/柴油/天然气/原煤低位发热量...',
  `category`     VARCHAR(32) NOT NULL COMMENT '类别: ENERGY/MATERIAL/TRANSPORT/PROCESS/WASTE',
  `factor_value` DECIMAL(18,6) NOT NULL COMMENT '排放因子值(kgCO2e/unit)',
  `unit`         VARCHAR(32) NOT NULL COMMENT '单位',
  `scope`        VARCHAR(8) DEFAULT NULL COMMENT '排放范围: 1/2/3',
  `version`      VARCHAR(32) NOT NULL DEFAULT 'V1.0' COMMENT '版本号',
  `source_org`   VARCHAR(64) DEFAULT NULL COMMENT '来源机构/标准: 国家发改委/IPCC/省级实测...',
  `owner_org_id` BIGINT UNSIGNED DEFAULT NULL COMMENT '归属机构id(NULL为平台/省厅统一下发)',
  `data_scope`   VARCHAR(16) NOT NULL DEFAULT 'PLATFORM' COMMENT '数据范围: PLATFORM平台/GOV省厅/ENTERPRISE企业',
  `valid_from`   DATE DEFAULT NULL COMMENT '生效日期',
  `valid_to`     DATE DEFAULT NULL COMMENT '失效日期',
  `status`       VARCHAR(16) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING待审核/EFFECTIVE生效/EXPIRED失效',
  `audit_by`     BIGINT UNSIGNED DEFAULT NULL COMMENT '审核人id',
  `audit_time`   DATETIME DEFAULT NULL COMMENT '审核时间',
  `create_time`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`      TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_factor_code_ver` (`factor_code`,`version`),
  KEY `idx_factor_category` (`category`),
  KEY `idx_factor_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='排放因子库表';

-- 24. 碳核算任务表
DROP TABLE IF EXISTS `carbon_task`;
CREATE TABLE `carbon_task` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_no`         VARCHAR(64) NOT NULL COMMENT '核算任务编号',
  `org_id`          BIGINT UNSIGNED NOT NULL COMMENT '企业机构id',
  `product_id`      BIGINT UNSIGNED DEFAULT NULL COMMENT '产品id',
  `facility_id`     BIGINT UNSIGNED DEFAULT NULL COMMENT '工序/设施id(选填)',
  `period_type`     VARCHAR(16) NOT NULL COMMENT '周期类型: MONTH/YEAR',
  `period`          VARCHAR(16) NOT NULL COMMENT '核算周期: 2026-11 或 2026',
  `method`          VARCHAR(32) NOT NULL DEFAULT 'ISO14067' COMMENT '核算方法: ISO14067/PAS2050/GHG_PROTOCOL/CBAM/EPD',
  `boundary`        VARCHAR(255) DEFAULT NULL COMMENT '系统边界描述',
  `total_co2e`      DECIMAL(18,6) DEFAULT NULL COMMENT '总排放(kgCO2e)',
  `co2e_per_unit`   DECIMAL(18,6) DEFAULT NULL COMMENT '单位产品碳足迹(kgCO2e/功能单位)',
  `scope1_co2e`     DECIMAL(18,6) DEFAULT NULL COMMENT '范围一(kgCO2e)',
  `scope2_co2e`     DECIMAL(18,6) DEFAULT NULL COMMENT '范围二(kgCO2e)',
  `scope3_co2e`     DECIMAL(18,6) DEFAULT NULL COMMENT '范围三(kgCO2e)',
  `calc_status`     VARCHAR(16) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT草稿/CALCULATING核算中/CALCULATED已核算/SUBMITTED已提交/REJECTED退回',
  `calc_log`        JSON DEFAULT NULL COMMENT '核算过程日志',
  `create_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by`       BIGINT UNSIGNED DEFAULT NULL COMMENT '创建人id',
  `deleted`         TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_no` (`task_no`),
  KEY `idx_task_org_period` (`org_id`,`period`),
  KEY `idx_task_status` (`calc_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='碳核算任务表';

-- 25. 核算结果明细表
DROP TABLE IF EXISTS `carbon_result_item`;
CREATE TABLE `carbon_result_item` (
  `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_id`      BIGINT UNSIGNED NOT NULL COMMENT '核算任务id',
  `item_type`    VARCHAR(32) NOT NULL COMMENT '明细类型: 消耗项/排放源/范围汇总',
  `item_name`    VARCHAR(128) NOT NULL COMMENT '明细名称',
  `quantity`     DECIMAL(18,6) DEFAULT NULL COMMENT '活动数据量',
  `unit`         VARCHAR(16) DEFAULT NULL COMMENT '单位',
  `factor_id`    BIGINT UNSIGNED DEFAULT NULL COMMENT '因子id',
  `factor_value` DECIMAL(18,6) DEFAULT NULL COMMENT '因子值',
  `co2e`         DECIMAL(18,6) DEFAULT NULL COMMENT '碳排放(kgCO2e)',
  `ratio`        DECIMAL(7,4) DEFAULT NULL COMMENT '占比(0-1)',
  `scope`        VARCHAR(8) DEFAULT NULL COMMENT '排放范围: 1/2/3',
  PRIMARY KEY (`id`),
  KEY `idx_result_task` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='核算结果明细表';

-- 26. 碳排放核算报告表
DROP TABLE IF EXISTS `carbon_report`;
CREATE TABLE `carbon_report` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `report_no`       VARCHAR(64) NOT NULL COMMENT '报告编号',
  `org_id`          BIGINT UNSIGNED NOT NULL COMMENT '企业机构id',
  `task_id`         BIGINT UNSIGNED NOT NULL COMMENT '核算任务id',
  `product_id`      BIGINT UNSIGNED DEFAULT NULL COMMENT '产品id',
  `report_name`     VARCHAR(128) NOT NULL COMMENT '报告名称',
  `report_type`     VARCHAR(32) DEFAULT NULL COMMENT '报告类型: CARBON_FOOTPRINT/ANNUAL_GHG',
  `period`          VARCHAR(16) NOT NULL COMMENT '核算周期',
  `total_co2e`      DECIMAL(18,6) DEFAULT NULL COMMENT '总排放(kgCO2e)',
  `intensity`       DECIMAL(18,6) DEFAULT NULL COMMENT '碳强度(kgCO2e/功能单位)',
  `echarts_config`  JSON DEFAULT NULL COMMENT '图表配置(复现可视化)',
  `report_file_id`  BIGINT UNSIGNED DEFAULT NULL COMMENT '报告文件id(sys_file)',
  `status`          VARCHAR(16) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT/GENERATING/PUBLISHED',
  `hash_value`      CHAR(64) DEFAULT NULL COMMENT '报告哈希值(防篡改)',
  `generate_time`   DATETIME DEFAULT NULL COMMENT '生成时间',
  `create_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by`       BIGINT UNSIGNED DEFAULT NULL COMMENT '创建人id',
  `deleted`         TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_report_no` (`report_no`),
  KEY `idx_report_org` (`org_id`,`period`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='碳排放核算报告表';

-- 27. 出海合规数据包表
DROP TABLE IF EXISTS `data_package`;
CREATE TABLE `data_package` (
  `id`               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `package_no`       VARCHAR(64) NOT NULL COMMENT '数据包编号',
  `org_id`           BIGINT UNSIGNED NOT NULL COMMENT '企业机构id',
  `product_id`       BIGINT UNSIGNED DEFAULT NULL COMMENT '产品id',
  `name`             VARCHAR(128) NOT NULL COMMENT '数据包名称',
  `package_type`     VARCHAR(32) NOT NULL COMMENT '合规类型: CBAM/EU_BATTERY/EPD/GENERAL',
  `target_region`    VARCHAR(64) DEFAULT NULL COMMENT '目标地区: 欧盟/美国/日本...',
  `standard`         VARCHAR(64) DEFAULT NULL COMMENT '适用标准: CBAM实施条例/欧盟电池法案...',
  `period`           VARCHAR(16) NOT NULL COMMENT '数据周期',
  `package_file_id`  BIGINT UNSIGNED DEFAULT NULL COMMENT '打包文件id(zip)',
  `encrypt_flag`     TINYINT NOT NULL DEFAULT 1 COMMENT '是否加密: 0否/1是',
  `hash_value`       CHAR(64) DEFAULT NULL COMMENT '包哈希值',
  `status`           VARCHAR(16) NOT NULL DEFAULT 'BUILDING' COMMENT 'BUILDING组装中/BUILT已生成/SUBMITTED已提交/REVIEWING核查中/RETURNED退回/PASSED通过',
  `submit_time`      DATETIME DEFAULT NULL COMMENT '提交时间',
  `create_time`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by`        BIGINT UNSIGNED DEFAULT NULL COMMENT '创建人id',
  `deleted`          TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_package_no` (`package_no`),
  KEY `idx_package_org` (`org_id`,`package_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='出海合规数据包表';

-- 28. 数据包明细表
DROP TABLE IF EXISTS `data_package_item`;
CREATE TABLE `data_package_item` (
  `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `package_id`  BIGINT UNSIGNED NOT NULL COMMENT '数据包id',
  `item_type`   VARCHAR(32) NOT NULL COMMENT '明细类型: REPORT报告/ACTIVITY活动数据/FACTOR因子/SUPPLY供应链/CERT凭证',
  `item_name`   VARCHAR(128) DEFAULT NULL COMMENT '明细名称',
  `ref_type`    VARCHAR(32) DEFAULT NULL COMMENT '引用对象类型: carbon_report/ent_activity_data/emission_factor/sc_material_flow',
  `ref_id`      BIGINT UNSIGNED DEFAULT NULL COMMENT '引用对象id',
  `include_flag` TINYINT NOT NULL DEFAULT 1 COMMENT '是否纳入: 0否/1是',
  PRIMARY KEY (`id`),
  KEY `idx_pkg_item` (`package_id`,`item_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='数据包明细表';

-- 29. 碳足迹护照申请表（双轨流程：省厅初审 → 第三方核查）
DROP TABLE IF EXISTS `passport_application`;
CREATE TABLE `passport_application` (
  `id`                 BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `application_no`     VARCHAR(64) NOT NULL COMMENT '申请编号',
  `org_id`             BIGINT UNSIGNED NOT NULL COMMENT '申请企业id',
  `product_id`         BIGINT UNSIGNED DEFAULT NULL COMMENT '产品id',
  `data_package_id`    BIGINT UNSIGNED DEFAULT NULL COMMENT '数据包id',
  `apply_type`         VARCHAR(32) NOT NULL COMMENT '申请类型: CBAM/EU_BATTERY/CARBON_FOOTPRINT',
  `apply_desc`         TEXT DEFAULT NULL COMMENT '申请说明',
  `status`             VARCHAR(20) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT草稿/PENDING_GOV待省厅初审/GOV_REJECTED省厅退回/PENDING_AGENCY待核查/AGENCY_REJECTED核查退回/APPROVED复核通过/ISSUED已签发/REJECTED驳回',
  `gov_reviewer_id`    BIGINT UNSIGNED DEFAULT NULL COMMENT '省厅初审人id',
  `gov_review_time`    DATETIME DEFAULT NULL COMMENT '省厅初审时间',
  `gov_review_comment` TEXT DEFAULT NULL COMMENT '省厅初审意见',
  `agency_id`          BIGINT UNSIGNED DEFAULT NULL COMMENT '核查机构id',
  `agency_reviewer_id` BIGINT UNSIGNED DEFAULT NULL COMMENT '第三方复核人id',
  `submit_time`        DATETIME DEFAULT NULL COMMENT '提交时间',
  `issued_time`        DATETIME DEFAULT NULL COMMENT '签发时间',
  `create_time`        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by`          BIGINT UNSIGNED DEFAULT NULL COMMENT '创建人id',
  `deleted`            TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_app_no` (`application_no`),
  KEY `idx_app_org` (`org_id`,`status`),
  KEY `idx_app_agency` (`agency_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='碳足迹护照申请表';

-- 30. 碳足迹护照表（已签发护照 + 防伪二维码）
DROP TABLE IF EXISTS `carbon_passport`;
CREATE TABLE `carbon_passport` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `passport_no`     VARCHAR(64) NOT NULL COMMENT '护照编号',
  `application_id`  BIGINT UNSIGNED NOT NULL COMMENT '申请id',
  `org_id`          BIGINT UNSIGNED NOT NULL COMMENT '企业id',
  `product_id`      BIGINT UNSIGNED DEFAULT NULL COMMENT '产品id',
  `product_name`    VARCHAR(128) DEFAULT NULL COMMENT '产品名称(签发快照)',
  `standard`        VARCHAR(64) DEFAULT NULL COMMENT '签发标准',
  `total_co2e`      DECIMAL(18,6) DEFAULT NULL COMMENT '核证总排放(kgCO2e)',
  `intensity`       DECIMAL(18,6) DEFAULT NULL COMMENT '碳足迹强度(kgCO2e/功能单位)',
  `valid_from`      DATE DEFAULT NULL COMMENT '有效期起',
  `valid_to`        DATE DEFAULT NULL COMMENT '有效期止',
  `verify_token`    VARCHAR(64) NOT NULL COMMENT '验真令牌(二维码内容)',
  `qr_img_file_id`  BIGINT UNSIGNED DEFAULT NULL COMMENT '二维码图片文件id',
  `passport_file_id` BIGINT UNSIGNED DEFAULT NULL COMMENT '护照文件id(pdf/png)',
  `seal_img_url`    VARCHAR(255) DEFAULT NULL COMMENT '签发印章地址',
  `signer_name`     VARCHAR(64) DEFAULT NULL COMMENT '签发人姓名',
  `hash_value`      CHAR(64) DEFAULT NULL COMMENT '护照哈希值',
  `status`          VARCHAR(16) NOT NULL DEFAULT 'VALID' COMMENT 'VALID有效/EXPIRED过期/REVOKED吊销',
  `issue_time`      DATETIME NOT NULL COMMENT '签发时间',
  `create_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_passport_no` (`passport_no`),
  UNIQUE KEY `uk_passport_token` (`verify_token`),
  KEY `idx_passport_org` (`org_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='碳足迹护照表';

-- ============================================================================
-- 五、AI 域：AI 碳管家对话 / OCR 任务
-- ============================================================================

-- 31. AI 对话会话表
DROP TABLE IF EXISTS `ai_conversation`;
CREATE TABLE `ai_conversation` (
  `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id`     BIGINT UNSIGNED NOT NULL COMMENT '用户id',
  `org_id`      BIGINT UNSIGNED DEFAULT NULL COMMENT '机构id',
  `session_id`  VARCHAR(64) NOT NULL COMMENT '会话标识(前端维护)',
  `title`       VARCHAR(128) DEFAULT NULL COMMENT '会话标题',
  `model`       VARCHAR(64) DEFAULT NULL COMMENT '使用模型: qwen-plus...',
  `status`      VARCHAR(16) NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE/CLOSED',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_conv_user` (`user_id`,`create_time`),
  KEY `idx_conv_session` (`session_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI对话会话表';

-- 32. AI 对话消息表
DROP TABLE IF EXISTS `ai_message`;
CREATE TABLE `ai_message` (
  `id`               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `conversation_id`  BIGINT UNSIGNED NOT NULL COMMENT '会话id',
  `role`             VARCHAR(16) NOT NULL COMMENT '角色: USER/ASSISTANT/SYSTEM',
  `content`          MEDIUMTEXT NOT NULL COMMENT '消息内容',
  `model`            VARCHAR(64) DEFAULT NULL COMMENT '模型',
  `prompt_tokens`    INT DEFAULT NULL COMMENT '输入token数',
  `completion_tokens` INT DEFAULT NULL COMMENT '输出token数',
  `latency_ms`       INT DEFAULT NULL COMMENT '响应耗时(毫秒)',
  `error_msg`        VARCHAR(500) DEFAULT NULL COMMENT '错误信息',
  `create_time`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_msg_conv` (`conversation_id`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI对话消息表';

-- 33. OCR 识别任务表（异步解耦，供化验单等业务调用）
DROP TABLE IF EXISTS `ocr_task`;
CREATE TABLE `ocr_task` (
  `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_id`       BIGINT UNSIGNED DEFAULT NULL COMMENT '机构id',
  `file_id`      BIGINT UNSIGNED NOT NULL COMMENT '待识别文件id(sys_file)',
  `biz_type`     VARCHAR(32) NOT NULL DEFAULT 'LAB_REPORT' COMMENT '业务类型: LAB_REPORT...',
  `biz_id`       BIGINT UNSIGNED DEFAULT NULL COMMENT '关联业务id(lab_report.id)',
  `engine`       VARCHAR(16) NOT NULL DEFAULT 'ALIYUN' COMMENT '引擎: ALIYUN/PADDLE',
  `doc_type`     VARCHAR(32) DEFAULT NULL COMMENT '文档类型: 表格/全文',
  `status`       VARCHAR(16) NOT NULL DEFAULT 'QUEUED' COMMENT 'QUEUED排队/RUNNING处理中/SUCCESS成功/FAILED失败',
  `result_json`  JSON DEFAULT NULL COMMENT '识别结果',
  `error_msg`    VARCHAR(500) DEFAULT NULL COMMENT '错误信息',
  `duration_ms`  INT DEFAULT NULL COMMENT '耗时(毫秒)',
  `create_time`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `finish_time`  DATETIME DEFAULT NULL COMMENT '完成时间',
  PRIMARY KEY (`id`),
  KEY `idx_ocr_biz` (`biz_type`,`biz_id`),
  KEY `idx_ocr_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OCR识别任务表';

-- ============================================================================
-- 六、省厅监管域：初审台 / 异常预警 / 核查任务 / H5 打卡
-- ============================================================================

-- 34. 智能初审任务表
DROP TABLE IF EXISTS `gov_review_task`;
CREATE TABLE `gov_review_task` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_no`        VARCHAR(64) NOT NULL COMMENT '初审任务编号',
  `data_type`      VARCHAR(20) NOT NULL COMMENT '待审数据类型: APPLICATION护照申请/PACKAGE数据包/REPORT报告',
  `source_org_id`  BIGINT UNSIGNED NOT NULL COMMENT '来源企业id',
  `source_biz_id`  BIGINT UNSIGNED NOT NULL COMMENT '来源业务id',
  `status`         VARCHAR(20) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING待审/AUTO_PASS自动通过/ALERT有预警/PASS人工通过/REJECT退回',
  `rule_hits`      JSON DEFAULT NULL COMMENT '命中的规则(JSON)',
  `anomaly_count`  INT NOT NULL DEFAULT 0 COMMENT '异常项数量',
  `reviewer_id`    BIGINT UNSIGNED DEFAULT NULL COMMENT '人工审核人id',
  `review_comment` TEXT DEFAULT NULL COMMENT '审核意见',
  `review_time`    DATETIME DEFAULT NULL COMMENT '审核时间',
  `create_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_review_task_no` (`task_no`),
  KEY `idx_review_status` (`status`,`create_time`),
  KEY `idx_review_source` (`source_org_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='智能初审任务表';

-- 35. 异常数据预警记录表
DROP TABLE IF EXISTS `gov_anomaly_alert`;
CREATE TABLE `gov_anomaly_alert` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `alert_no`       VARCHAR(64) NOT NULL COMMENT '预警编号',
  `org_id`         BIGINT UNSIGNED NOT NULL COMMENT '企业id',
  `data_type`      VARCHAR(20) NOT NULL COMMENT '数据对象: ACTIVITY/REPORT/PACKAGE/APPLICATION',
  `data_id`        BIGINT UNSIGNED NOT NULL COMMENT '数据对象id',
  `rule_code`      VARCHAR(64) NOT NULL COMMENT '命中的规则编码',
  `alert_level`    VARCHAR(8) NOT NULL DEFAULT 'LOW' COMMENT '级别: LOW/MEDIUM/HIGH',
  `alert_desc`     VARCHAR(500) DEFAULT NULL COMMENT '预警描述',
  `compare_desc`   TEXT DEFAULT NULL COMMENT '比对详情(阈值vs实际)',
  `status`         VARCHAR(16) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING待处理/HANDLED已处理/IGNORED已忽略',
  `handler_id`     BIGINT UNSIGNED DEFAULT NULL COMMENT '处理人id',
  `handle_time`    DATETIME DEFAULT NULL COMMENT '处理时间',
  `create_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_alert_no` (`alert_no`),
  KEY `idx_alert_org_status` (`org_id`,`status`),
  KEY `idx_alert_level` (`alert_level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='异常数据预警记录表';

-- 36. 线下核查任务表（派发至执法员/核查员）
DROP TABLE IF EXISTS `gov_inspection_task`;
CREATE TABLE `gov_inspection_task` (
  `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_no`      VARCHAR(64) NOT NULL COMMENT '核查任务编号',
  `title`        VARCHAR(128) NOT NULL COMMENT '任务标题',
  `org_id`       BIGINT UNSIGNED NOT NULL COMMENT '被核查企业id',
  `type`         VARCHAR(32) NOT NULL COMMENT '任务类型: 数据核查/现场执法/飞检',
  `leader_id`    BIGINT UNSIGNED DEFAULT NULL COMMENT '派发人id',
  `executor_id`  BIGINT UNSIGNED NOT NULL COMMENT '执行人id',
  `plan_start`   DATETIME DEFAULT NULL COMMENT '计划开始时间',
  `plan_end`     DATETIME DEFAULT NULL COMMENT '计划结束时间',
  `address`      VARCHAR(255) DEFAULT NULL COMMENT '核查地址',
  `lng`          DECIMAL(11,7) DEFAULT NULL COMMENT '目标经度(网点)',
  `lat`          DECIMAL(10,7) DEFAULT NULL COMMENT '目标纬度',
  `radius_m`     INT DEFAULT NULL COMMENT '有效打卡半径(米)',
  `desc`         TEXT DEFAULT NULL COMMENT '任务说明',
  `status`       VARCHAR(16) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING待接收/DOING进行中/DONE已完成/OVERDUE已逾期/CANCELED已取消',
  `finish_time`  DATETIME DEFAULT NULL COMMENT '完成时间',
  `create_time`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`      TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_inspection_no` (`task_no`),
  KEY `idx_inspection_executor` (`executor_id`,`status`),
  KEY `idx_inspection_org` (`org_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='线下核查任务表';

-- 37. 执法打卡记录表（H5 GPS + 拍照）
DROP TABLE IF EXISTS `gov_checkin_record`;
CREATE TABLE `gov_checkin_record` (
  `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_id`      BIGINT UNSIGNED NOT NULL COMMENT '核查任务id',
  `user_id`      BIGINT UNSIGNED NOT NULL COMMENT '打卡人id',
  `checkin_time` DATETIME NOT NULL COMMENT '打卡时间',
  `lng`          DECIMAL(11,7) NOT NULL COMMENT '经度',
  `lat`          DECIMAL(10,7) NOT NULL COMMENT '纬度',
  `accuracy`     DECIMAL(10,2) DEFAULT NULL COMMENT '定位精度(米)',
  `address`      VARCHAR(255) DEFAULT NULL COMMENT '逆地理编码地址【外部API:MAP】',
  `distance_m`   DECIMAL(12,2) DEFAULT NULL COMMENT '与目标点距离(米)',
  `photo_file_id` BIGINT UNSIGNED DEFAULT NULL COMMENT '现场照片文件id(sys_file)',
  `device_info`  VARCHAR(255) DEFAULT NULL COMMENT '设备信息',
  `status`       VARCHAR(16) NOT NULL DEFAULT 'VALID' COMMENT 'VALID有效打卡/OFFSITE离场打卡/ABNORMAL异常',
  `create_time`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_checkin_task` (`task_id`),
  KEY `idx_checkin_user` (`user_id`,`checkin_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='执法打卡记录表';

-- ============================================================================
-- 七、第三方核查机构域：国际合规复核
-- ============================================================================

-- 38. 国际合规复核表
DROP TABLE IF EXISTS `agency_review`;
CREATE TABLE `agency_review` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `review_no`       VARCHAR(64) NOT NULL COMMENT '复核编号',
  `application_id`  BIGINT UNSIGNED NOT NULL COMMENT '护照申请id',
  `package_id`      BIGINT UNSIGNED DEFAULT NULL COMMENT '数据包id',
  `agency_id`       BIGINT UNSIGNED NOT NULL COMMENT '核查机构id',
  `reviewer_id`     BIGINT UNSIGNED DEFAULT NULL COMMENT '复核人id',
  `standard`        VARCHAR(64) DEFAULT NULL COMMENT '复核标准: ISO14067/CBAM/EU_BATTERY',
  `conclusion`      VARCHAR(16) DEFAULT NULL COMMENT '结论: PASS通过/FAIL不通过',
  `score`           DECIMAL(6,2) DEFAULT NULL COMMENT '评分(选填)',
  `checklist_json`  JSON DEFAULT NULL COMMENT '核对清单逐项结论',
  `review_comment`  TEXT DEFAULT NULL COMMENT '复核意见',
  `status`          VARCHAR(16) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING待复核/REVIEWING复核中/DONE已完成',
  `review_time`     DATETIME DEFAULT NULL COMMENT '复核完成时间',
  `create_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_agency_review_no` (`review_no`),
  KEY `idx_agency_review_app` (`application_id`),
  KEY `idx_agency_review_org` (`agency_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='国际合规复核表';

