-- ============================================================================
-- v1.1 增量（按更新后需求）：物流追踪 / 绿色金融 / 电子签章 / 大屏快照 /
--      供应链合同 / 外部API调用日志 / 公开验真日志；化验单支持多模态视觉识别
-- 说明：v1.0 共 38 张表，v1.1 新增 8 张，合计 46 张核心表。
-- ============================================================================

-- 39. 物流追踪表（车牌起终点 → 高德地图模拟轨迹 → 里程）
DROP TABLE IF EXISTS `ent_logistics_trip`;
CREATE TABLE `ent_logistics_trip` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `trip_no`         VARCHAR(64) NOT NULL COMMENT '运输单号',
  `org_id`          BIGINT UNSIGNED NOT NULL COMMENT '企业机构id',
  `sc_flow_id`      BIGINT UNSIGNED DEFAULT NULL COMMENT '关联供应链流转id(sc_material_flow)',
  `plate_no`        VARCHAR(16) DEFAULT NULL COMMENT '车牌号',
  `transport_mode`  VARCHAR(32) NOT NULL COMMENT '运输方式: 公路/铁路/水运',
  `start_name`      VARCHAR(128) DEFAULT NULL COMMENT '起点名称',
  `start_lng`       DECIMAL(11,7) DEFAULT NULL COMMENT '起点经度',
  `start_lat`       DECIMAL(10,7) DEFAULT NULL COMMENT '起点纬度',
  `end_name`        VARCHAR(128) DEFAULT NULL COMMENT '终点名称',
  `end_lng`         DECIMAL(11,7) DEFAULT NULL COMMENT '终点经度',
  `end_lat`         DECIMAL(10,7) DEFAULT NULL COMMENT '终点纬度',
  `route_json`      JSON DEFAULT NULL COMMENT '轨迹点数组(高德模拟轨迹/打开地图划线)',
  `mileage_km`      DECIMAL(12,3) DEFAULT NULL COMMENT '里程(km)',
  `status`          VARCHAR(16) NOT NULL DEFAULT 'IN_TRANSIT' COMMENT 'IN_TRANSIT运输中/ARRIVED已到达',
  `start_time`      DATETIME DEFAULT NULL COMMENT '发车时间',
  `arrive_time`     DATETIME DEFAULT NULL COMMENT '到达时间',
  `create_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`         TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_trip_no` (`trip_no`),
  KEY `idx_trip_org` (`org_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='物流追踪表';

-- 40. 绿色金融信誉档案表（信誉分 + 预授信额度，测度数据见公式 F7/F8）
DROP TABLE IF EXISTS `fin_credit_profile`;
CREATE TABLE `fin_credit_profile` (
  `id`                  BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_id`              BIGINT UNSIGNED NOT NULL COMMENT '企业机构id',
  `score`               DECIMAL(6,2) NOT NULL COMMENT '信誉分(0~100)',
  `level`               VARCHAR(8) NOT NULL COMMENT '信用等级: AAA/AA/A/B',
  `score_detail_json`   JSON DEFAULT NULL COMMENT '评分明细(完整性/及时性/稳定性/合规)',
  `base_quota`          DECIMAL(16,2) DEFAULT NULL COMMENT '基准额度(万元,按行业规模分档)',
  `credit_quota`        DECIMAL(16,2) DEFAULT NULL COMMENT '预授信额度(万元)',
  `history_count`       INT NOT NULL DEFAULT 0 COMMENT '历史核算任务数',
  `apply_count`         INT NOT NULL DEFAULT 0 COMMENT '历史申报(护照)数',
  `calc_time`           DATETIME DEFAULT NULL COMMENT '最近评分时间',
  `create_time`         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_fin_org` (`org_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='绿色金融信誉档案表';

-- 41. 绿色金融授信申请表
DROP TABLE IF EXISTS `fin_credit_apply`;
CREATE TABLE `fin_credit_apply` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `apply_no`        VARCHAR(64) NOT NULL COMMENT '授信申请编号',
  `org_id`          BIGINT UNSIGNED NOT NULL COMMENT '企业机构id',
  `bank_name`       VARCHAR(128) DEFAULT NULL COMMENT '意向金融机构',
  `apply_quota`     DECIMAL(16,2) NOT NULL COMMENT '申请额度(万元)',
  `purpose`         VARCHAR(255) DEFAULT NULL COMMENT '资金用途(减排改造/供应链/经营周转)',
  `remark`          TEXT DEFAULT NULL COMMENT '备注',
  `status`          VARCHAR(16) NOT NULL DEFAULT 'SUBMITTED' COMMENT 'SUBMITTED已提交/APPROVING审批中/APPROVED通过/REJECTED驳回',
  `create_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`         TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_fin_apply_no` (`apply_no`),
  KEY `idx_fin_apply_org` (`org_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='绿色金融授信申请表';

-- 42. 供应链合同表（供应商资质/合同附件，隶属供应链协同模块）
DROP TABLE IF EXISTS `sc_supplier_contract`;
CREATE TABLE `sc_supplier_contract` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_id`         BIGINT UNSIGNED NOT NULL COMMENT '企业机构id',
  `partner_id`     BIGINT UNSIGNED NOT NULL COMMENT '伙伴id(sc_supplier)',
  `contract_no`    VARCHAR(64) DEFAULT NULL COMMENT '合同编号',
  `contract_name`  VARCHAR(128) DEFAULT NULL COMMENT '合同名称',
  `contract_type`  VARCHAR(32) DEFAULT NULL COMMENT '合同类型: 采购/销售/长期协议',
  `amount`         DECIMAL(18,2) DEFAULT NULL COMMENT '合同金额(元)',
  `sign_date`      DATE DEFAULT NULL COMMENT '签订日期',
  `valid_to`       DATE DEFAULT NULL COMMENT '有效期至',
  `file_id`        BIGINT UNSIGNED DEFAULT NULL COMMENT '合同/资质附件id(sys_file)',
  `qualification_url` VARCHAR(255) DEFAULT NULL COMMENT '供应商资质文件地址',
  `status`         VARCHAR(16) NOT NULL DEFAULT 'VALID' COMMENT 'VALID有效/EXPIRED过期/TERMINATED终止',
  `create_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`        TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_sc_contract_org` (`org_id`,`partner_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='供应链合同表';

-- 43. 初审意见书表（电子签章：初审通过后印章图片叠加到审批单）
DROP TABLE IF EXISTS `gov_approval_letter`;
CREATE TABLE `gov_approval_letter` (
  `id`                 BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `letter_no`          VARCHAR(64) NOT NULL COMMENT '意见书编号',
  `application_id`     BIGINT UNSIGNED DEFAULT NULL COMMENT '护照申请id',
  `review_task_id`     BIGINT UNSIGNED DEFAULT NULL COMMENT '关联初审任务id(gov_review_task)',
  `org_id`             BIGINT UNSIGNED NOT NULL COMMENT '被审企业id',
  `content`            TEXT DEFAULT NULL COMMENT '意见书正文',
  `stamped_file_id`    BIGINT UNSIGNED DEFAULT NULL COMMENT '盖章后意见书文件id(sys_file)',
  `seal_url`           VARCHAR(255) DEFAULT NULL COMMENT '所用印章图片地址',
  `stamp_by`           BIGINT UNSIGNED DEFAULT NULL COMMENT '盖章人id',
  `stamp_time`         DATETIME DEFAULT NULL COMMENT '盖章时间',
  `hash_value`         CHAR(64) DEFAULT NULL COMMENT '盖章文件哈希(存证)',
  `create_time`        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_letter_no` (`letter_no`),
  KEY `idx_letter_app` (`application_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='初审意见书表(电子签章)';

-- 44. 大屏态势快照表（定时预聚合，大屏秒开）
DROP TABLE IF EXISTS `gov_summary_snapshot`;
CREATE TABLE `gov_summary_snapshot` (
  `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `snapshot_type` VARCHAR(32) NOT NULL COMMENT '快照类型: REGION_CITY省→市州/INDUSTRY行业/PRODUCT产品/TREND趋势',
  `period`       VARCHAR(16) DEFAULT NULL COMMENT '统计周期',
  `dim_key`      VARCHAR(64) NOT NULL COMMENT '维度键(市州/行业名)',
  `co2e_total`   DECIMAL(18,6) DEFAULT NULL COMMENT '排放总量(kgCO2e)',
  `org_count`    INT NOT NULL DEFAULT 0 COMMENT '企业数',
  `intensity_avg` DECIMAL(18,6) DEFAULT NULL COMMENT '平均碳强度',
  `extra_json`   JSON DEFAULT NULL COMMENT '附加指标',
  `snapshot_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '快照时间',
  PRIMARY KEY (`id`),
  KEY `idx_snap` (`snapshot_type`,`snapshot_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='大屏态势快照表';

-- 45. 外部 API 调用日志表（LLM/多模态/高德/OSS 调用留痕 + 成本统计）
DROP TABLE IF EXISTS `sys_api_invoke_log`;
CREATE TABLE `sys_api_invoke_log` (
  `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `api_type`     VARCHAR(32) NOT NULL COMMENT 'API类型: LLM/VISION/AMAP/OCR/OSS/SMS',
  `biz_type`     VARCHAR(32) DEFAULT NULL COMMENT '业务场景: AI_CHAT/LAB_RECOGNIZE/GEOCODE/CHECKIN_ADDR...',
  `org_id`       BIGINT UNSIGNED DEFAULT NULL COMMENT '机构id',
  `user_id`      BIGINT UNSIGNED DEFAULT NULL COMMENT '用户id',
  `request_summary` VARCHAR(500) DEFAULT NULL COMMENT '请求摘要(脱敏)',
  `success`      TINYINT NOT NULL DEFAULT 1 COMMENT '是否成功: 0否/1是',
  `cost_tokens`  INT DEFAULT NULL COMMENT '消耗token(LLM/多模态)',
  `duration_ms`  INT DEFAULT NULL COMMENT '耗时(毫秒)',
  `error_msg`    VARCHAR(500) DEFAULT NULL COMMENT '错误信息',
  `create_time`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '调用时间',
  PRIMARY KEY (`id`),
  KEY `idx_api_type` (`api_type`,`create_time`),
  KEY `idx_api_org` (`org_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='外部API调用日志表';

-- 46. 公开验真访问日志表（防扫描/审计）
DROP TABLE IF EXISTS `sys_verify_log`;
CREATE TABLE `sys_verify_log` (
  `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `passport_id`  BIGINT UNSIGNED DEFAULT NULL COMMENT '护照id',
  `passport_no`  VARCHAR(64) DEFAULT NULL COMMENT '护照编号',
  `verify_token` VARCHAR(64) NOT NULL COMMENT '验真令牌',
  `result`       VARCHAR(16) NOT NULL COMMENT '验真结果: PASS/FAIL',
  `ip`           VARCHAR(64) DEFAULT NULL COMMENT '访问IP',
  `user_agent`   VARCHAR(255) DEFAULT NULL COMMENT 'UA',
  `verify_time`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '验真时间',
  PRIMARY KEY (`id`),
  KEY `idx_verify_token` (`verify_token`,`verify_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公开验真访问日志表';

-- ----------------------------------------------------------------------------
-- v1.1 化验单表增强：支持多模态视觉大模型识别（qwen-vl 等）
-- ----------------------------------------------------------------------------
ALTER TABLE `lab_report`
  ADD COLUMN `vision_engine`  VARCHAR(16) DEFAULT NULL COMMENT '视觉引擎: QWEN_VL/GPT4V/PADDLE_NONE' AFTER `ocr_engine`,
  ADD COLUMN `vision_model`   VARCHAR(64) DEFAULT NULL COMMENT '视觉模型名: qwen-vl-plus...' AFTER `vision_engine`,
  ADD COLUMN `vision_prompt`  VARCHAR(500) DEFAULT NULL COMMENT '读图提示词快照' AFTER `vision_model`,
  ADD COLUMN `raw_result_json` JSON DEFAULT NULL COMMENT '大模型原始返回' AFTER `ocr_result_json`;

