-- ----------------------------------------------------------------------------
-- v1.2 企业端「整改计划生成与预算预估」模块（超级管理员端：全链路审计与存证中心配套）
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS `ent_rectify_issue`;
CREATE TABLE `ent_rectify_issue` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `issue_no`      VARCHAR(64)  NOT NULL COMMENT '整改事项编号',
  `org_id`        BIGINT UNSIGNED NOT NULL COMMENT '企业id',
  `source_type`   VARCHAR(32)  NOT NULL COMMENT '来源: 初审退回/波动预警/核查退回',
  `topic`         VARCHAR(500) NOT NULL COMMENT '事项描述',
  `risk_level`    VARCHAR(8)   NOT NULL DEFAULT 'MEDIUM' COMMENT '风险: HIGH/MEDIUM/LOW',
  `status`        VARCHAR(20)  NOT NULL DEFAULT 'PENDING' COMMENT '状态: PENDING待整改/RECTIFYING整改中/CLOSED已闭环',
  `plan_json`     JSON DEFAULT NULL COMMENT 'AI生成的整改措施清单(JSON数组)',
  `budget_json`   JSON DEFAULT NULL COMMENT '预算预估明细(JSON数组, 含10%预备费汇总)',
  `hash_chain_seq` BIGINT UNSIGNED DEFAULT NULL COMMENT '哈希链区块序号(存证)',
  `submit_time`   DATETIME DEFAULT NULL COMMENT '提交审批时间',
  `create_time`   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`       TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rectify_no` (`issue_no`),
  KEY `idx_rectify_org_status` (`org_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='企业整改事项表(整改计划生成与预算预估)';

DROP TABLE IF EXISTS `ent_rectify_budget`;
CREATE TABLE `ent_rectify_budget` (
  `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `issue_id`    BIGINT UNSIGNED NOT NULL COMMENT '整改事项id',
  `cat`         VARCHAR(64)  NOT NULL COMMENT '费用科目: 设备改造/检测费/培训费/第三方服务',
  `basis`       VARCHAR(255) DEFAULT NULL COMMENT '预算依据(数量×单价说明)',
  `qty`         DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT '数量',
  `unit`        VARCHAR(16)  DEFAULT NULL COMMENT '单位: 项/点位/人天/批次',
  `price`       DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT '单价(元)',
  `amount`      DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT '小计(元)',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_rectify_budget_issue` (`issue_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='整改预算明细表';

