-- ----------------------------------------------------------------------------
-- v1.3 国家级审批部门（终审发证 / 跨国互认 / 黑名单 / 国际关税预警）4 张核心表
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS `nat_final_issue`;
CREATE TABLE `nat_final_issue` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `application_no`  VARCHAR(64)  NOT NULL COMMENT '申请单号（关联 passport_application.no）',
  `passport_no`     VARCHAR(64)  DEFAULT NULL COMMENT '护照编号（终审通过签发后生成）',
  `org_id`          BIGINT UNSIGNED DEFAULT NULL COMMENT '企业 id',
  `ent_name`        VARCHAR(200) DEFAULT NULL COMMENT '企业名称',
  `period`          VARCHAR(32)  DEFAULT NULL COMMENT '核算期',
  `product_name`    VARCHAR(200) DEFAULT NULL COMMENT '产品 / 声明单位',
  `agency_conclusion` VARCHAR(16) DEFAULT NULL COMMENT '核查机构复核结论：PASSED / REJECTED',
  `status`          VARCHAR(16)  NOT NULL DEFAULT 'PENDING' COMMENT '终审状态：PENDING / APPROVED / REJECTED',
  `total_co2e`      DECIMAL(18,4) DEFAULT NULL COMMENT '碳足迹总量 tCO2e',
  `intensity`       DECIMAL(18,6) DEFAULT NULL COMMENT '产品碳强度 tCO2e/t',
  `hash_chain_seq`  BIGINT UNSIGNED DEFAULT NULL COMMENT 'F10 哈希链区块号（防篡改存证）',
  `verify_token`    VARCHAR(64)  DEFAULT NULL COMMENT 'F11 防伪验证令牌（二维码内容）',
  `signer_name`     VARCHAR(100) DEFAULT NULL COMMENT '签发人（国家级终审专员）',
  `issue_time`      DATETIME DEFAULT NULL COMMENT '签发时间',
  `create_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`         TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_nat_issue_app` (`application_no`),
  KEY `idx_nat_issue_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='国家级终审与发证记录表';

DROP TABLE IF EXISTS `nat_mutual_scan`;
CREATE TABLE `nat_mutual_scan` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `passport_no`   VARCHAR(64)  NOT NULL COMMENT '护照编号',
  `country`       VARCHAR(64)  NOT NULL COMMENT '查验国家 / 地区',
  `city`          VARCHAR(80)  DEFAULT NULL COMMENT '查验城市',
  `ip`            VARCHAR(64)  DEFAULT NULL COMMENT '来源 IP',
  `verify_result` VARCHAR(16)  NOT NULL DEFAULT 'VERIFIED' COMMENT '查验结果：VERIFIED / DISCREPANCY',
  `scan_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '扫码时间',
  `deleted`       TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_nat_scan_time` (`scan_time`),
  KEY `idx_nat_scan_country` (`country`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跨国互认扫码查验记录表';

DROP TABLE IF EXISTS `nat_blacklist`;
CREATE TABLE `nat_blacklist` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ent_name`       VARCHAR(200) NOT NULL COMMENT '违规企业名称',
  `org_id`         BIGINT UNSIGNED DEFAULT NULL COMMENT '企业 id',
  `reason`         VARCHAR(500) NOT NULL COMMENT '违规原因',
  `severity`       VARCHAR(8)   NOT NULL DEFAULT 'MEDIUM' COMMENT '严重级别：HIGH / MEDIUM',
  `penalty_status` VARCHAR(16)  NOT NULL DEFAULT 'NOTIFIED' COMMENT '处置状态：FROZEN 已冻结 / NOTIFIED 已通报 / OBSERVING 观察中',
  `source`         VARCHAR(32)  DEFAULT NULL COMMENT '证据来源：数据核查 / 海关协查 / 匿名举报',
  `evidence_no`    VARCHAR(64)  DEFAULT NULL COMMENT '证据编号',
  `create_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`        TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_nat_black_status` (`penalty_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='国家级黑名单通报系统表';

DROP TABLE IF EXISTS `nat_tariff_rule`;
CREATE TABLE `nat_tariff_rule` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `industry`       VARCHAR(64)  NOT NULL COMMENT '行业：钢铁 / 铝 / 水泥 / 化肥 / 电力 / 氢',
  `product_scope`  VARCHAR(255) DEFAULT NULL COMMENT '产品范围描述（CN 编码）',
  `tariff_rate`    DECIMAL(12,4) NOT NULL COMMENT 'CBAM 碳关税税率（EUR/tCO2e）',
  `free_allowance` DECIMAL(5,2)  NOT NULL DEFAULT 0 COMMENT '免费配额比例（%）',
  `effective_from` DATE NOT NULL COMMENT '生效日期',
  `note`           VARCHAR(255) DEFAULT NULL COMMENT '影响测算口径说明',
  `status`         VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE / FROZEN',
  `create_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted`        TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_nat_tariff_industry` (`industry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='国际关税预警规则表（CBAM）';

