-- 十、演示数据扩充（v1.4）：机构/用户/字典/企业/产品/核算/出口合规/物流/金融
-- 说明：
--   1) 与既有角色种子 sys_role(1~7) 对接，用户角色绑定见 sys_user_role。
--   2) org_id 约定：1=省厅、11~19=市州局、2/3=核查机构、999=国家级终审中心、
--      1001~1015=企业（含 1009/1012/1015 黑名单企业）。
--   3) 出口方向覆盖：欧盟(德/法/荷/比/意)、美国、日本、韩国、东南亚、中东、澳洲，
--      对应数据包 data_package、碳护照 carbon_passport、物流 ent_logistics_trip、
--      跨国查验 nat_mutual_scan 四类出海证据链。
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 10.1 机构：平台/省厅/市州局/核查机构/国家级中心/企业
