INSERT INTO `sc_collab_task` (`id`,`org_id`,`partner_id`,`task_type`,`title`,`content`,`deadline`,`status`) VALUES
  (4401,1002,4219,'DATA_COLLECT','请巴斯夫补充采购周期数据','请提供2026年Q4正极材料采购周期及包装运输方式，用于范围三核算。','2026-12-05 18:00:00','PENDING'),
  (4402,1002,4220,'CONFIRM','确认Northvolt批次氢氟酸限值','确认出口瑞典批次重金属与杂质限值是否符合欧盟电池法案。','2026-12-03 18:00:00','DOING'),
  (4403,1001,4216,'FEEDBACK','日本客户对精煤灰分反馈','出口日本精煤灰分8.8%，请反馈下一季度指标要求。','2026-12-10 18:00:00','DONE'),
  (4404,1003,4224,'DATA_COLLECT','HELM AG 追加运输凭证','请提供汉堡港卸货与内陆转运的运输凭证，补全CBAM证据链。','2026-12-08 18:00:00','PENDING'),
  (4405,1004,4227,'CONFIRM','确认Trimet铝锭PFC口径','请确认原铝锭PFC核算口径并按EU ETS报告。','2026-12-12 18:00:00','PENDING'),
  (4406,1005,4230,'DATA_COLLECT','德国特钢客户碳足迹边界','请确认优特钢棒材交付边界与功能单位。','2026-12-01 18:00:00','OVERDUE'),
  (4407,1006,4231,'FEEDBACK','Boral水泥氯离子指标反馈','出口澳洲水泥氯离子0.012%，客户要求出具英文质检单。','2026-12-15 18:00:00','DOING'),
  (4408,1008,4233,'CONFIRM','新加坡氢气纯度确认','请确认灰氢纯度99.9%与CO含量检测方法。','2026-12-06 18:00:00','PENDING'),
  (4409,1010,4237,'DATA_COLLECT','三星SDI前驱体追溯信息收集','请采集NCM811前驱体镍钴资源产地与隐含碳凭证。','2026-12-20 18:00:00','PENDING'),
