INSERT INTO `sys_notification` (`id`,`user_id`,`biz_type`,`title`,`content`,`read_flag`,`read_time`,`create_time`) VALUES
  (7101,2,'REVIEW','数据包初审结果已出，请及时查看','您有一条数据包初审反馈，结论与整改口径见详情页。',0,NULL,'2026-11-01 00:00:00'),
  (7102,5,'INSPECTION','现场核查任务已派发，请做好迎检准备','省厅已向您派发现场核查任务，计划时间与路线以任务详情为准。',1,'2026-11-27 02:00:00','2026-11-02 01:00:00'),
  (7103,4,'PASSPORT','碳护照已签发，可在验真中心公开查验','您申请的碳护照已完成国家级签发，可通过防伪二维码进行公开验真。',1,'2026-11-27 03:00:00','2026-11-03 02:00:00'),
  (7104,6,'PACKAGE','出口数据包已进入第三方核查环节','您的出口合规数据包已进入第三方核查机构复核流程。',0,NULL,'2026-11-04 03:00:00'),
  (7105,8,'REVIEW','异常波动预警已触发，请核实活动数据','系统检测到活动数据异常波动，请点击进入预警中心核对。',1,'2026-11-27 05:00:00','2026-11-05 04:00:00'),
